package com.bank.puzzle;

import java.util.ArrayList;
import java.util.List;

public class AutoboxingPuzzle {

    public static String demonstrate() {
        StringBuilder output = new StringBuilder();

        List<Short> list = new ArrayList<>();
        for (short i = 0; i < 5; i++) {
            list.add(i);              // autoboxes short → Short
            output.append("Added ").append(i).append(" → list=").append(list).append("\n");

            if (list.size() > 1) {
                // TRAP! list.remove(i) — i is short, widened to int
                // Calls remove(int index), NOT remove(Short value)!
                list.remove((int) i);  // removes element at INDEX i, not value i!
                output.append("  remove(").append(i).append(") by INDEX → list=").append(list).append("\n");
            }
        }

        output.append("\n--- Fix: use remove((Short) i) for value removal ---\n");
        List<Short> fixedList = new ArrayList<>();
        for (short i = 0; i < 5; i++) {
            fixedList.add(i);
            if (fixedList.size() > 1) {
                fixedList.remove(Short.valueOf(i));  // removes by VALUE (Short object)
            }
        }
        output.append("Fixed list: ").append(fixedList);

        return output.toString();
    }
}
