package com.bank.puzzle;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class AutoboxingPuzzleTest {

    @Test
    void removeIntCallsRemoveByIndex() {
        List<Short> list = new ArrayList<>(List.of((short) 10, (short) 20, (short) 30));
        list.remove(1);  // removes element at INDEX 1 (which is 20), NOT value 1
        assertThat(list).containsExactly((short) 10, (short) 30);
    }

    @Test
    void removeShortObjectCallsRemoveByValue() {
        List<Short> list = new ArrayList<>(List.of((short) 10, (short) 20, (short) 30));
        list.remove(Short.valueOf((short) 20));  // removes VALUE 20
        assertThat(list).containsExactly((short) 10, (short) 30);
    }

    @Test
    void theAutoboxingTrap() {
        List<Integer> list = new ArrayList<>(List.of(0, 1, 2, 3));
        // list.remove(2) → removes element at INDEX 2 (value 2), list becomes [0, 1, 3]
        list.remove(2);
        assertThat(list).containsExactly(0, 1, 3);

        // list.remove(Integer.valueOf(1)) → removes VALUE 1
        list.remove(Integer.valueOf(1));
        assertThat(list).containsExactly(0, 3);
    }
}
