package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.ArrayList;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

class ShortRemoveTrapTest {

    @Test
    void removeByIndexVsByValue() {
        List<Short> byIndex = new ArrayList<>(List.of((short) 10, (short) 20, (short) 30));
        byIndex.remove(1);                       // int → remove(index 1) → drops 20
        assertThat(byIndex).containsExactly((short) 10, (short) 30);

        List<Short> byValue = new ArrayList<>(List.of((short) 10, (short) 20, (short) 30));
        byValue.remove(Short.valueOf((short) 10)); // Object → remove value 10
        assertThat(byValue).containsExactly((short) 20, (short) 30);
    }
}
